import * as tt from "thinkthen";

// each ticket goes to the team its words name:
// billing, shipping, and account
const options = ["billing", "shipping", "account"];
for (const text of ["I was billed twice for one order.",
    "My parcel is a week late.",
    "I am locked out of my account."]) {
  console.log(await tt.choose("Which team owns this?",
      text, { options }));
}
